import type { MvBook } from '../molytvoslov';
const D: MvBook[] = [{"u":"Свята Пасха","e":"Holy Pascha","secs":[{"h":"Стихира, глас 6","ps":["Воскресе́ніє Твоє́ Христе́ Спа́се, / а́нгели пою́ть на небесі́х, / і нас на землі́ сподо́би / чи́стим се́рдцем / Тебе́ сла́вити."]},{"h":"Тропар, глас 5","ps":["Христо́с воскре́се із ме́ртвих, / сме́ртію смерть попра́в, / і су́щим во гробі́х живо́т дарова́в.","Іпакої́, глас 4","Предвари́вшия у́тро я́же о Марі́ї / і обрі́тшия ка́мень отвале́н от гро́ба, / сли́шаху от а́нгела: во сві́ті присносу́щнім Су́щаго, / с ме́ртвими что і́щете я́ко челові́ка; / ви́діте гро́бния пелени́, теці́те, і ми́ру пропові́діте, / я́ко воста́ Госпо́дь, умертви́вий смерть: / я́ко єсть Син Бо́га, спаса́ющаго род челові́чеський."]},{"h":"Кондак, глас 8","ps":["А́ще і во гроб снизше́л єси́ Безсме́ртне, / но а́дову разруши́л єси́ си́лу, і воскре́сл єси́ я́ко побіди́тель Христе́ Бо́же, / жена́м мироно́сицям віща́вий, ра́дуйтеся: / і Твої́м апо́столом мир да́руяй, / па́дшим подая́й воскресе́ніє."]},{"h":"Задостойник, глас 1","ps":["А́нгел вопія́ше Благода́тній: / Чи́стая Ді́во, ра́дуйся, / і па́ки реку́, ра́дуйся: / Твой Син воскре́се / тридне́вен от гро́ба, / і ме́ртвия воздви́гнувий, / лю́діє веселі́теся.","§Ірмос 9-ї пісні:","Світи́ся, світи́ся но́вий Ієрусали́ме: / сла́ва бо Госпо́дня на Тебі́ возсія́. / Лику́й ни́ні, і весели́ся Сіо́не. / Ти же Чи́стая красу́йся Богоро́дице, / о воста́нії рождества́ Твоєго́."]}],"notes":[]},{"u":"Віддання Пасхи","e":"Leave-taking of Pascha","secs":[{"h":"Тропар у Неділю про сліпородженого, глас 5","ps":["Собезнача́льноє Сло́во Отцю́ і Ду́хові, / от Ді́ви ро́ждшеєся на спасе́ніє на́ше, / воспої́м, ві́рнії, і поклоні́мся, / я́ко благоволи́ пло́тію взи́ти на крест, / і смерть претерпі́ти, / і воскреси́ти уме́ршія // сла́вним воскресе́нієм Свої́м."]},{"h":"Кондак у Неділю про сліпородженого, глас 4","ps":["Душе́внима очи́ма осліпле́н, / к Тебі́, Христе́, прихожду́, / я́коже сліпи́й от рожде́нія, / покая́нієм зову́ Ті: // Ти су́щих во Тьмі Світ пресві́тлий."]},{"h":"Стихира Пасхи, глас 6","ps":["Воскресе́ніє Твоє́ Христе́ Спа́се, / а́нгели пою́ть на небесі́х, / і нас на землі́ сподо́би / чи́стим се́рдцем / Тебе́ сла́вити."]},{"h":"Тропар Пасхи, глас 5","ps":["Христо́с воскре́се із ме́ртвих, / сме́ртію смерть попра́в, / і су́щим во гробі́х живо́т дарова́в."]},{"h":"Кондак Пасхи, глас 8","ps":["А́ще і во гроб снизше́л єси́ Безсме́ртне, / но а́дову разруши́л єси́ си́лу, і воскре́сл єси́ я́ко побіди́тель Христе́ Бо́же, / жена́м мироно́сицям віща́вий, ра́дуйтеся: / і Твої́м апо́столом мир да́руяй, / па́дшим подая́й воскресе́ніє."]},{"h":"Задостойник Пасхи, глас 1","ps":["А́нгел вопія́ше Благода́тній: / Чи́стая Ді́во, ра́дуйся, / і па́ки реку́, ра́дуйся: / Твой Син воскре́се / тридне́вен от гро́ба, / і ме́ртвия воздви́гнувий, / лю́діє веселі́теся.","§Ірмос 9-ї пісні:","Світи́ся, світи́ся но́вий Ієрусали́ме: / сла́ва бо Госпо́дня на Тебі́ возсія́. / Лику́й ни́ні, і весели́ся Сіо́не. / Ти же Чи́стая красу́йся Богоро́дице, / о воста́нії рождества́ Твоєго́."]}],"notes":[]},{"u":"Вхід Господній в Єрусалим","e":"Entry of the Lord into Jerusalem","secs":[{"h":"Тропар, глас 1","ps":["О́бщеє воскресе́ніє / пре́жде Твоєя́ стра́сти увіря́я / із ме́ртвих воздви́гл єси́ Ла́заря, Христе́ Бо́же. / Ті́мже і ми, я́ко о́троци побі́ди зна́менія нося́ще, / Тебі́ Побіди́телю сме́рти вопіє́м: / оса́нна во ви́шніх, // благослове́н Гряди́й во І́м'я Госпо́днє.","Ін тропа́р, глас 4","Спогре́бшеся Тебі́ креще́нієм, Христе́ Бо́же наш, / безсме́ртния жи́зні сподо́бихомся воскресе́нієм Твої́м, / і воспіва́юще зове́м: / оса́нна во ви́шніх, // благослове́н Гряди́й во І́м'я Госпо́днє."]},{"h":"Кондак, глас 6","ps":["На престо́лі на небесі́, / на жреб'я́ті на землі́ носи́мий, Христе́ Бо́же, / А́нгелов хвале́ніє і діте́й воспіва́ніє / прия́л єси́ зову́щих Ті: // благослове́н єси́, гряди́й Ада́ма воззва́ти."]},{"h":"Величання","ps":["Велича́єм Тя, Живода́вче Христе́, Оса́нна во ви́шніх і ми Тебі́ вопіє́м Благослове́н Гряди́й во І́м'я Госпо́днє."]},{"h":"Задостойник","ps":["Бог Госпо́дь, і яви́ся нам, соста́віте пра́здник, і веселя́щеся прийді́те, возвели́чим Христа́, с ва́їями і ві́твми, пі́сньми зову́ще: благослове́н Гряди́й во і́м'я Го́спода Спа́са на́шего."]}],"notes":[]},{"u":"Передсвяття Різдва Христового","e":"Forefeast of the Nativity of Christ","secs":[{"h":"Тропар, глас 4","ps":["Гото́вися, Вифлеє́ме, / отве́рзися всім, Єде́ме, / красу́йся, Євфра́фо, / я́ко дре́во живота́ во верте́пі процвіте́ от Ді́ви: / рай бо О́ноя чре́во яви́ся ми́сленний, / в не́мже Боже́ственний сад, / от него́же я́дше, жи́ви бу́дем, / не я́коже Ада́м у́мрем. // Христо́с ражда́ється пре́жде па́дший возста́вити о́браз."]},{"h":"Кондак, глас 3","ps":["Ді́ва днесь преві́чноє Сло́во / во верте́пі гряде́ть роди́ти неізрече́нно: / лику́й, вселе́нная, усли́шавши, / просла́ви со А́нгели і па́стирми / хотя́щаго яви́тися // Отроча́ Мла́до, Преві́чнаго Бо́га."]}],"notes":[]},{"u":"Передсвяття Богоявлення","e":"Forefeast of Theophany","secs":[{"h":"Тропар, глас 4","ps":["Гото́вися, Завуло́не, / і красу́йся, Неффали́ме, / Іорда́не ріко́, ста́ни, / подими́, взигра́я, крести́тися гряду́ща Влади́ку. / Весели́ся, Ада́ме с прама́терію, / не кри́йта себі́, я́коже в раї́ пре́жде, / і́бо, на́ги ви́дів ви, яви́ся, / да облече́ть в пе́рвую оде́жду: // Христо́с яви́ся, всю твар хотя́ обнови́ти."]},{"h":"Кондак, глас 4","ps":["Во струя́х днесь Іорда́нських бив, Госпо́дь / Іоа́нну вопіє́ть: / не убо́йся крести́ти М'я, / спасти́ бо прийдо́х // Ада́ма первозда́ннаго."]}],"notes":[]},{"u":"Передсвяття Стрітення Господнього","e":"Forefeast of the Presentation of the Lord","secs":[{"h":"Тропар, глас 1","ps":["Небе́сний лик Небе́сних А́нгел, / прини́к на зе́млю, прише́дше зрить я́ко Младе́нця, / носи́ма ко хра́му, Перворожде́нна всея́ тва́рі от Ма́тере Неіскусому́жния, // предпра́зднственную у́бо с на́ми пою́ть піснь, ра́дующеся."]},{"h":"Кондак, глас 6","ps":["Со Отце́м Сло́во сий неви́димо, / ни́ні у́бо ви́дим єсть пло́тію: / неізрече́нно от Ді́ви роди́ся / і на руку́ ста́рчу дає́ться святи́телю. / Поклоні́мся Тому́, // і́стинному Бо́гу на́шему."]}],"notes":[]},{"u":"Передсвяття Благовіщення Пресвятої Богородиці","e":"Forefeast of the Annunciation","secs":[{"h":"Тропар, глас 4","ps":["Днесь всеми́рния ра́дости нача́тки / предпра́зднственноє воспі́ти повеліва́ють: / се бо Гавриї́л прихо́дить, / Ді́ві нося́ благові́стіє, / і к Ней вопіє́ть: / ра́дуйся, Благода́тная, / Госпо́дь с Тобо́ю."]},{"h":"Кондак, глас 8","ps":["Всім земни́м нача́ло спасе́нія на́шего Ти єси́, Богоро́дице Ді́во, / Бо́жий бо служи́тель с Небе́с по́слан предста́ти Тебі́, / вели́кий чинонача́льник Гавриї́л, / ра́дость обра́дованную Ті принесе́. / Тім всі зове́м Ті: / ра́дуйся, Неві́сто Неневі́стная."]}],"notes":[]},{"u":"Передсвяття Преображення Господнього","e":"Forefeast of the Transfiguration","secs":[{"h":"Тропар, глас 4","ps":["Христо́во преображе́ніє предусря́щем, / сві́тло торжеству́юще предпра́зднственная, ві́рнії, і возопії́м: / приспі́ день боже́ственнаго весе́лія, / восхо́дить на го́ру Фаво́рськую Влади́ка, // Божества́ Своєго́ облиста́ти красоту́."]},{"h":"Кондак, глас 4","ps":["Боже́ственним днесь преображе́нієм / челові́чеськоє все єстество́ / просіява́єть боже́ственно, / во весе́лії зову́щеє: // преобразу́ється Христо́с, спаса́яй вся."]}],"notes":[]},{"u":"Передсвяття Успіння Пресвятої Богородиці","e":"Forefeast of the Dormition","secs":[{"h":"Тропар, глас 4","ps":["Лю́діє, предигра́йте, / рука́ми пле́щуще ві́рно, / і любо́вію собері́теся, / днесь ра́дующеся / і сві́тло восклиця́юще всі весе́лієм: / Бо́жия бо Ма́ти і́мать от земни́х к Ви́шнім прейти́ сла́вно, // Ю́же пі́сньми при́сно я́ко Богоро́дицю сла́вим."]},{"h":"Кондак, глас 4","ps":["В сла́вній па́м'яті Твоє́й / вселе́нная, невеще́ственним Ду́хом іспещре́на, / у́мно с весе́лієм зове́ть Тебі́: / ра́дуйся, Ді́во, // христия́н похвало́."]}],"notes":[]},{"u":"Передсвяття Різдва Пресвятої Богородиці","e":"Forefeast of the Nativity of the Theotokos","secs":[{"h":"Тропар, глас 4","ps":["От ко́рене Ієссе́єва і от чресл Дави́дових / Богоотрокови́ця Марія́м ражда́ється днесь нам, / ра́достію бо ра́дуються вся́чеськая і обновля́ються. / Сра́дуйтеся ку́пно, Не́бо і земля́, / восхвалі́те Ю, оте́чествія язи́ков! / Іоаки́м весели́ться, і А́нна торжеству́єть, зову́щи: // непло́ди ражда́єть Богоро́дицю і Пита́тельницю Жи́зні на́шея."]},{"h":"Кондак, глас 3","ps":["Ді́ва днесь і Богоро́диця Марі́я, / черто́г безконе́чний Небе́снаго Жениха́, ражда́ється / от непло́дове, Бо́жиїм Сові́том, / колесни́ця Сло́ва благоукраша́ється: / на сіє́ бо преднарече́ся Боже́ственная двер // і Ма́ти су́щия Жи́зні."]}],"notes":[]},{"u":"Передсвяття Воздвиження Чесного і Животворящого Хреста Господнього","e":"Forefeast of the Exaltation of the Cross","secs":[{"h":"Тропар, глас 4","ps":["Животворя́щий Крест Твоєя́ бла́гости, / єго́же дарова́л єси́ нам недосто́йним, Го́споди, / Тебі́ прино́сим в моли́тву: / спаси́ лю́ди і град Твой моля́щийся, Богоро́дицею, // Єди́не Человіколю́бче."]}],"notes":[]},{"u":"Передсвяття Введення в храм Пресвятої Богородиці","e":"Forefeast of the Entry of the Theotokos into the Temple","secs":[{"h":"Тропар, глас 4","ps":["Ра́дость предобруча́єть всім А́нна ни́ні, / печа́лі сопроти́вний плод прозя́бши, Єди́ну Присноді́ву, / Ю́же і приво́дить, моли́тви ісполня́ющи, / днесь веселя́щися, в храм Госпо́день, // я́ко су́щий храм Бо́га Сло́ва і Ма́тер Чи́стую."]},{"h":"Кондак, глас 4","ps":["Весе́лія днесь вселе́нная іспо́лнися вся / в благознамени́том пра́здниці Богоро́диці, зову́щи: // Та єсть сінь Небе́сная."]}],"notes":[]},{"u":"Обрізання Господнє","e":"Circumcision of the Lord","secs":[{"h":"Тропар, глас 1","ps":["На Престо́лі огнезра́чнім / во Ви́шніх сідя́й со Отце́м Безнача́льним і Боже́ственним Твої́м Ду́хом, / благоволи́л єси́ роди́тися на землі́ / от Отрокови́ці Неіскусому́жния, Твоєя́ Ма́тере, Ісу́се, / сего́ ра́ди і обрі́зан бил єси́, я́ко Челові́к осьмодне́вний. / Сла́ва всеблаго́му Твоєму́ сові́ту, / сла́ва смотре́нію Твоєму́, / сла́ва снизхожде́нію Твоєму́, Єди́не Человіколю́бче."]},{"h":"Кондак, глас 3","ps":["Всіх Госпо́дь обрі́заніє терпи́ть / і челові́чеськая прегріше́нія, я́ко Благ, обрі́зуєть, / дає́ть спасе́ніє днесь ми́ру. / Ра́дується же во Ви́шніх і Созда́телев ієра́рх, / і світоно́сний, Боже́ственний таї́нник Христо́во Васи́лій."]},{"h":"Величання","ps":["Велича́єм Тя, Живода́вче Христе́, / і почита́єм пречи́стия пло́ті Твоєя́ / зако́нноє обрі́заніє."]}],"notes":[]},{"u":"Різдво Іоанна Предтечі","e":"Nativity of John the Forerunner","secs":[{"h":"Тропар, глас 4","ps":["Проро́че і Предте́че прише́ствія Христо́ва, / досто́йно восхвали́ти тя недоумі́єм ми, любо́вію чту́щії тя: / непло́дство бо ро́ждшия і о́тчеє безгла́сіє разріши́ся / сла́вним і честни́м твої́м рождество́м, // і воплоще́ніє Си́на Бо́жия ми́рові пропові́дується."]},{"h":"Кондак, глас 3","ps":["Пре́жде непло́ди днесь Христо́ва Предте́чу ражда́єть, / і той єсть ісполне́ніє вся́каго проро́чества: / Єго́же бо проро́ци пропові́даша, / на Сего́ во Іорда́ні ру́ку положи́в, / яви́ся Бо́жия Сло́ва проро́к, пропові́дник, // вку́пі і Предте́ча."]},{"h":"Величання","ps":["Велича́єм тя, Предте́че Спа́сов Іоа́нне, і чтим є́же от непло́дове пресла́вноє рождество́ твоє́."]}],"notes":[]},{"u":"Святих первоверховних апостолів Петра і Павла","e":"Holy Chief Apostles Peter and Paul","secs":[{"h":"Тропар, глас 4","ps":["Апо́столов первопресто́льници / і вселе́нния учи́теліє, / Влади́ку всіх молі́те / мир вселе́нній дарова́ти // і душа́м на́шим ве́лію ми́лость."]},{"h":"Кондак, глас 2","ps":["Тве́рдия і боговіща́нния пропові́дателі, / верх апо́столов Твої́х, Го́споди, / прия́л єси́ в наслажде́ніє благи́х Твої́х і поко́й: / болі́зні бо о́ніх і смерть прия́л єси́ па́че вся́каго всепло́дія, // Єди́не, сві́дий серде́чная."]},{"h":"Величання","ps":["Велича́єм вас, / апо́столи Христо́ви Пе́тре і Па́вле, / весь мир уче́ньми свої́ми просвети́вшия / і вся конці́ ко Христу́ приве́дшия."]}],"notes":[]},{"u":"Усікновення глави Іоанна Предтечі","e":"Beheading of John the Forerunner","secs":[{"h":"Тропар, глас 2","ps":["Па́м'ять пра́веднаго с похвала́ми, / тебі́ же довлі́єть свиді́тельство Госпо́днє, Предте́че: / показа́л бо ся єси́ воі́стину і проро́ков честні́йший, / я́ко і в струя́х крести́ти сподо́бился єси́ Пропові́даннаго. / Ті́мже за і́стину пострада́в, ра́дуяся, / благовісти́л єси́ і су́щим во а́ді Бо́га, я́вльшагося пло́тію, / взе́млющаго гріх ми́ра // і подаю́щаго нам ве́лію ми́лость."]},{"h":"Кондак, глас 5","ps":["Предте́чево сла́вноє усікнове́ніє / смотре́ніє бисть ні́коє Боже́ственноє, / да і су́щим во а́ді Спа́сово пропові́сть прише́ствіє. / Да рида́єть у́бо Іроді́я, / беззако́нноє уби́йство іспроси́вши: / не зако́н бо Бо́жий, ні живи́й вік возлюби́, // но притво́рний, привре́менний."]},{"h":"Величання","ps":["Велича́єм тя, / Крести́телю Спа́сов Іоа́нне, / і почита́єм всі / честни́я твоєя́ глави́ // усікнове́ніє."]}],"notes":[]},{"u":"Покров Пресвятої Богородиці","e":"Protection of the Theotokos","secs":[{"h":"Тропар, глас 4","ps":["Днесь, благові́рнії лю́діє, сві́тло пра́зднуєм, / осіня́ємі Твої́м, Богома́ти, прише́ствієм, / і к Твоєму́ взира́юще пречи́стому о́бразу, уми́льно глаго́лем: / покри́й нас честни́м Твої́м Покро́вом / і ізба́ви нас от вся́каго зла, / моля́щи Си́на Твоєго́, Христа́ Бо́га на́шего, // спасти́ ду́ші на́ша."]},{"h":"Кондак, глас 3","ps":["Ді́ва днесь предстої́ть в це́ркві / і с ли́ки святи́х неви́димо за ни мо́литься Бо́гу, / А́нгели со архієре́ї покланя́ються, / апо́столи же со проро́ки ликовству́ють: // нас бо ра́ди мо́лить Богоро́диця Преві́чнаго Бо́га."]},{"h":"Величання","ps":["Велича́єм Тя, / Пресвята́я Ді́во, / і чтим Покро́в Твой святи́й: / Тя бо ви́ді святи́й Андре́й на возду́сі, / за ни Христу́ моля́щуюся.","Ін велича́ніє","Велича́єм Тя, / Пресвята́я Ді́во, / Ма́ти Христа́, Бо́га на́шего, / і всесла́вний сла́вим Покро́в Твой.","Ін велича́ніє","Велича́єм Тя, / Пресвята́я Ді́во, / Ма́ти Христа́, Бо́га на́шего, / І́же к Си́ну Свої́ ру́ці простира́ющи, і о ми́рі моля́щися, / і честни́м Свої́м омофо́ром защища́ющи / град і лю́ди от враго́в на́ших."]}],"notes":[]},{"u":"Неділя про митаря і фарисея","e":"Sunday of the Publican and the Pharisee","secs":[{"ps":["По 50-м псалмі́","Сла́ва, глас 8: Покая́нія отве́рзи мі две́рі, Жизнода́вче, / у́тренюєть бо дух мой ко хра́му свято́му Твоєму́, / храм нося́й тіле́сний весь оскверне́н: / но я́ко щедр, очи́сти / благоутро́бною Твоє́ю ми́лостію.","І ни́ні, Богоро́дичен: На спасе́нія стезі́ наста́ви м'я, Богоро́дице, / сту́дними бо окаля́х ду́шу гріхми́, / і в лі́ності все житіє́ моє́ іжди́х: / но Твої́ми моли́твами / ізба́ви м'я от вся́кия нечистоти́.","Та́же, глас 6: Поми́луй м'я, Бо́же, / по вели́цій ми́лості Твоє́й, / і по мно́жеству щедро́т Твої́х, / очи́сти беззако́ніє моє́.","Мно́жества соді́янних мно́ю лю́тих помишля́я окая́нний, / трепе́щу стра́шнаго дне су́днаго: / но наді́яся на ми́лость благоутро́бія Твоєго́, / я́ко Дави́д вопію́ Ті: / поми́луй м'я, Бо́же, / по вели́цій Твоє́й ми́лості."]},{"h":"Кондак Неділі про митаря і фарисея, глас 4","ps":["Фарисе́єва убіжи́м високоглаго́ланія, / і митаре́ві научі́мся висоті́ глаго́л смире́нних, / покая́нієм взива́юще: / Спа́се ми́ра, // очи́сти раби́ Твоя́.","Ін конда́к Неді́ли о митарі́ і фарисе́є, глас 3","Воздиха́нія принесе́м мита́рськая Го́сподеві, / і к Нему́ присту́пим грі́шнії, я́ко Влади́ці: / хо́щеть бо спасе́нія всіх челові́ков, / оставле́ніє подає́ть всім ка́ющимся, / нас бо ра́ди воплоти́ся, Бог сий, // Отцю́ Собезнача́льний."]}],"notes":[]},{"u":"Неділя про блудного сина","e":"Sunday of the Prodigal Son","secs":[{"ps":["Псало́м 136","На ріка́х Вавило́нських, та́мо сідо́хом і пла́кахом, внегда́ пом'яну́ти нам Сіо́на. Аллилу́я. На ве́рбіїх посреді́ єго́ обі́сихом орга́ни на́ша. Аллилу́я. Я́ко та́мо вопроси́ша ни плі́ншії нас о словесі́х пі́сней і ве́дшії нас о пі́нії. Аллилу́я. Воспо́йте нам от пі́сней Сіо́нських. Аллилу́я. Ка́ко воспоє́м піснь Госпо́дню на землі́ чужде́й? Аллилу́я. А́ще забу́ду тебе́, Ієрусали́ме, забве́на бу́ди десни́ця моя́. Аллилу́я. Прильпни́ язи́к мой горта́ні моєму́, а́ще не пом'яну́ тебі́, а́ще не предложу́ Ієрусали́ма, я́ко в нача́лі весе́лія моєго́. Аллилу́я. Пом'яни́, Го́споди, си́ни Єдо́мськия, в день Ієрусали́мль, глаго́лющия: істоща́йте, істоща́йте до основа́ній єго́. Аллилу́я. Дщи Вавило́ня окая́нная. Блаже́н і́же возда́сть тебі́ воздая́ніє твоє́, є́же воздала́ єси́ нам. Аллилу́я. Блаже́н і́же і́меть, і разбіє́ть младе́нці твоя́ о ка́мень. Аллилу́я.","По 50-м псалмі́","Сла́ва, глас 8: Покая́нія отве́рзи мі две́рі, Жизнода́вче, / у́тренюєть бо дух мой ко хра́му свято́му Твоєму́, / храм нося́й тіле́сний весь оскверне́н: / но я́ко щедр, очи́сти / благоутро́бною Твоє́ю ми́лостію.","І ни́ні, Богоро́дичен: На спасе́нія стезі́ наста́ви м'я, Богоро́дице, / сту́дними бо окаля́х ду́шу гріхми́, / і в лі́ності все житіє́ моє́ іжди́х: / но Твої́ми моли́твами / ізба́ви м'я от вся́кия нечистоти́.","Та́же, глас 6: Поми́луй м'я, Бо́же, / по вели́цій ми́лості Твоє́й, / і по мно́жеству щедро́т Твої́х, / очи́сти беззако́ніє моє́.","Мно́жества соді́янних мно́ю лю́тих помишля́я окая́нний, / трепе́щу стра́шнаго дне су́днаго: / но наді́яся на ми́лость благоутро́бія Твоєго́, / я́ко Дави́д вопію́ Ті: / поми́луй м'я, Бо́же, / по вели́цій Твоє́й ми́лості."]},{"h":"Кондак Неділі про блудного сина, глас 3","ps":["Оте́чеськая сла́ви Твоєя́ удали́хся безу́мно, / в злих расточи́в, є́же мі пре́дал єси́ бога́тство. / Ті́мже Ті блу́днаго глас приношу́: / согріши́х пред Тобо́ю, О́тче ще́дрий, / прийми́ м'я ка́ющася, // і сотвори́ м'я я́ко єди́наго от нає́мник Твої́х."]}],"notes":[]},{"u":"Субота м’ясопусна. Вселенська батьківська субота","e":"Meatfare Saturday. Universal Saturday of the Departed","secs":[{"h":"Тропар, глас 8","ps":["Глубино́ю му́дрости человіколю́бно вся стро́яй, / і поле́зноє всім подава́яй, / єди́не Соді́телю, / упоко́й Го́споди, ду́ші раб Твої́х: / на Тя бо упова́ніє возложи́ша, / Творця́ і Зижди́теля і Бо́га на́шего.","Сла́ва, і ни́ні: Богоро́дичен","Тебі́ і сті́ну, і приста́нище і́мами, / і моли́твенницю благоприя́тну к Бо́гу, / Єго́же родила́ єси́ Богоро́дице безневі́стная, ві́рних спасе́ніє."]},{"h":"Кондак, глас 6","ps":["Со святи́ми упоко́й / Христе́, ду́ші раб Твої́х, / іді́же ність болі́знь, ні печа́ль, / ні воздиха́ніє, / но жизнь безконе́чная."]}],"notes":[]},{"u":"Неділя м’ясопусна. Про Страшний суд","e":"Meatfare Sunday. The Last Judgment","secs":[{"ps":["Псало́м 136","На ріка́х Вавило́нських, та́мо сідо́хом і пла́кахом, внегда́ пом'яну́ти нам Сіо́на. Аллилу́я. На ве́рбіїх посреді́ єго́ обі́сихом орга́ни на́ша. Аллилу́я. Я́ко та́мо вопроси́ша ни плі́ншії нас о словесі́х пі́сней і ве́дшії нас о пі́нії. Аллилу́я. Воспо́йте нам от пі́сней Сіо́нських. Аллилу́я. Ка́ко воспоє́м піснь Госпо́дню на землі́ чужде́й? Аллилу́я. А́ще забу́ду тебе́, Ієрусали́ме, забве́на бу́ди десни́ця моя́. Аллилу́я. Прильпни́ язи́к мой горта́ні моєму́, а́ще не пом'яну́ тебі́, а́ще не предложу́ Ієрусали́ма, я́ко в нача́лі весе́лія моєго́. Аллилу́я. Пом'яни́, Го́споди, си́ни Єдо́мськия, в день Ієрусали́мль, глаго́лющия: істоща́йте, істоща́йте до основа́ній єго́. Аллилу́я. Дщи Вавило́ня окая́нная. Блаже́н і́же возда́сть тебі́ воздая́ніє твоє́, є́же воздала́ єси́ нам. Аллилу́я. Блаже́н і́же і́меть, і разбіє́ть младе́нці твоя́ о ка́мень. Аллилу́я.","По 50-м псалмі́","Сла́ва, глас 8: Покая́нія отве́рзи мі две́рі, Жизнода́вче, / у́тренюєть бо дух мой ко хра́му свято́му Твоєму́, / храм нося́й тіле́сний весь оскверне́н: / но я́ко щедр, очи́сти / благоутро́бною Твоє́ю ми́лостію.","І ни́ні, Богоро́дичен: На спасе́нія стезі́ наста́ви м'я, Богоро́дице, / сту́дними бо окаля́х ду́шу гріхми́, / і в лі́ності все житіє́ моє́ іжди́х: / но Твої́ми моли́твами / ізба́ви м'я от вся́кия нечистоти́.","Та́же, глас 6: Поми́луй м'я, Бо́же, / по вели́цій ми́лості Твоє́й, / і по мно́жеству щедро́т Твої́х, / очи́сти беззако́ніє моє́.","Мно́жества соді́янних мно́ю лю́тих помишля́я окая́нний, / трепе́щу стра́шнаго дне су́днаго: / но наді́яся на ми́лость благоутро́бія Твоєго́, / я́ко Дави́д вопію́ Ті: / поми́луй м'я, Бо́же, / по вели́цій Твоє́й ми́лості."]},{"h":"Кондак, глас 1","ps":["Єгда́ при́йдеши, Бо́же, на зе́млю со сла́вою, / і трепе́щуть вся́чеськая: / ріка́ же о́гненная пред суди́щем влече́ть, / кни́ги разгиба́ються, і та́йная явля́ються; / тогда́ ізба́ви м'я от огня́ неугаси́маго, // і сподо́би м'я одесну́ю Тебе́ ста́ти, Судіє́ Пра́веднійший."]}],"notes":[]},{"u":"Субота сиропусна. Усіх преподобних отців, у подвигу просіявших","e":"Cheesefare Saturday. All Venerable Fathers Who Shone in Ascetic Struggle","secs":[{"h":"Тропар, глас 4","ps":["Бо́же оте́ць на́ших, / творя́й при́сно с на́ми по Твоє́й кро́тости, / не отста́ви ми́лость Твою́ от нас: / но моли́твами їх / в ми́рі упра́ви живо́т наш."]},{"h":"Кондак, глас 8","ps":["Я́ко благоче́стія пропові́дники, і нече́стія обузда́телі / богоно́сних собо́р уясни́л єси́, / подсо́лнечную осіява́ющия: / в ми́рі соверше́нном тіх моли́твами, / Тебі́ сла́в'ящия і велича́ющия сохрани́, / пою́щия Ті Го́споди: Аллилу́я."]}],"notes":[]},{"u":"Неділя сиропусна. Спомин вигнання Адама. Прощена неділя","e":"Cheesefare Sunday. Commemoration of Adam’s Expulsion. Forgiveness Sunday","secs":[{"ps":["Псало́м 136","На ріка́х Вавило́нських, та́мо сідо́хом і пла́кахом, внегда́ пом'яну́ти нам Сіо́на. Аллилу́я. На ве́рбіїх посреді́ єго́ обі́сихом орга́ни на́ша. Аллилу́я. Я́ко та́мо вопроси́ша ни плі́ншії нас о словесі́х пі́сней і ве́дшії нас о пі́нії. Аллилу́я. Воспо́йте нам от пі́сней Сіо́нських. Аллилу́я. Ка́ко воспоє́м піснь Госпо́дню на землі́ чужде́й? Аллилу́я. А́ще забу́ду тебе́, Ієрусали́ме, забве́на бу́ди десни́ця моя́. Аллилу́я. Прильпни́ язи́к мой горта́ні моєму́, а́ще не пом'яну́ тебі́, а́ще не предложу́ Ієрусали́ма, я́ко в нача́лі весе́лія моєго́. Аллилу́я. Пом'яни́, Го́споди, си́ни Єдо́мськия, в день Ієрусали́мль, глаго́лющия: істоща́йте, істоща́йте до основа́ній єго́. Аллилу́я. Дщи Вавило́ня окая́нная. Блаже́н і́же возда́сть тебі́ воздая́ніє твоє́, є́же воздала́ єси́ нам. Аллилу́я. Блаже́н і́же і́меть, і разбіє́ть младе́нці твоя́ о ка́мень. Аллилу́я.","По 50-м псалмі́","Сла́ва, глас 8: Покая́нія отве́рзи мі две́рі, Жизнода́вче, / у́тренюєть бо дух мой ко хра́му свято́му Твоєму́, / храм нося́й тіле́сний весь оскверне́н: / но я́ко щедр, очи́сти / благоутро́бною Твоє́ю ми́лостію.","І ни́ні, Богоро́дичен: На спасе́нія стезі́ наста́ви м'я, Богоро́дице, / сту́дними бо окаля́х ду́шу гріхми́, / і в лі́ності все житіє́ моє́ іжди́х: / но Твої́ми моли́твами / ізба́ви м'я от вся́кия нечистоти́.","Та́же, глас 6: Поми́луй м'я, Бо́же, / по вели́цій ми́лості Твоє́й, / і по мно́жеству щедро́т Твої́х, / очи́сти беззако́ніє моє́.","Мно́жества соді́янних мно́ю лю́тих помишля́я окая́нний, / трепе́щу стра́шнаго дне су́днаго: / но наді́яся на ми́лость благоутро́бія Твоєго́, / я́ко Дави́д вопію́ Ті: / поми́луй м'я, Бо́же, / по вели́цій Твоє́й ми́лості."]},{"h":"Кондак Неділі сиропусної, глас 6","ps":["Прему́дрости Наста́вниче, сми́сла Пода́телю, / нему́дрих Наказа́телю, і ни́щих Защи́тителю, / утверди́, вразуми́ се́рдце моє́, Влади́ко! / Ти даждь мі сло́во, О́тчеє Сло́во, / се бо устні́ мої́ не возбраню́, / во є́же зва́ти Тебі́: // Ми́лостиве, поми́луй м'я па́дшаго."]}],"notes":[]},{"u":"Субота першого тижня Великого посту. Великомученика Феодора Тирона","e":"Saturday of the First Week of Great Lent. Great Martyr Theodore the Recruit","secs":[{"h":"Тропар, глас 2","ps":["Ве́лія ві́ри ісправле́нія, / во істо́чниці пла́мене, я́ко на воді́ упокоє́нія, / святи́й му́ченик Фео́дор ра́довашеся; / огне́м бо всесожже́гся, / я́ко хліб сла́дкий Тро́йце принесе́ся. / Того́ моли́твами, Христе́ Бо́же, // спаси́ ду́ші на́ша."]},{"h":"Кондак, глас 8","ps":["Ві́ру Христо́ву, я́ко щит, внутр приї́м в се́рдці твоє́м, / проти́вния си́ли попра́л єси́ многострада́льче, / і вінце́м небе́сним вінча́лся єси́ ві́чно, // Фео́доре, я́ко непобіди́мий."]},{"h":"Величання","ps":["Велича́єм тя, / страстоте́рпче святи́й Фео́доре, / і чтим честна́я страда́нія твоя́, / я́же за Христа́ / претерпі́л єси́."]}],"notes":[]},{"u":"Неділя перша Великого посту. Торжество Православ’я","e":"First Sunday of Great Lent. Triumph of Orthodoxy","secs":[{"ps":["По 50-м псалмі́","Сла́ва, глас 8: Покая́нія отве́рзи мі две́рі, Жизнода́вче, / у́тренюєть бо дух мой ко хра́му свято́му Твоєму́, / храм нося́й тіле́сний весь оскверне́н: / но я́ко щедр, очи́сти / благоутро́бною Твоє́ю ми́лостію.","І ни́ні, Богоро́дичен: На спасе́нія стезі́ наста́ви м'я, Богоро́дице, / сту́дними бо окаля́х ду́шу гріхми́, / і в лі́ності все житіє́ моє́ іжди́х: / но Твої́ми моли́твами / ізба́ви м'я от вся́кия нечистоти́.","Та́же, глас 6: Поми́луй м'я, Бо́же, / по вели́цій ми́лості Твоє́й, / і по мно́жеству щедро́т Твої́х, / очи́сти беззако́ніє моє́.","Мно́жества соді́янних мно́ю лю́тих помишля́я окая́нний, / трепе́щу стра́шнаго дне су́днаго: / но наді́яся на ми́лость благоутро́бія Твоєго́, / я́ко Дави́д вопію́ Ті: / поми́луй м'я, Бо́же, / по вели́цій Твоє́й ми́лості."]},{"h":"Тропар Неділі Торжества Православ’я, глас 2","ps":["Пречи́стому О́бразу Твоєму́ покланя́ємся, Благи́й, / прося́ще проще́нія прегріше́ній на́ших, Христе́ Бо́же; / во́лею бо благоволи́л єси́ пло́тію взи́ти на крест, / да ізба́виши я́же созда́л єси́ от рабо́ти вра́жия. / Тім благода́рственно вопіє́м Ті: / ра́дости іспо́лнил єси́ вся, Спа́се наш, // прише́дий спасти́ мир."]},{"h":"Кондак Неділі Торжества Православ’я, глас 2","ps":["Неопи́санноє Сло́во О́тчеє, / із Тебе́, Богоро́дице, описа́ся воплоща́єм: / і оскве́рншійся о́браз в дре́внєє вообрази́в, / Боже́ственною добро́тою сміси́. / Но іспові́дающе спасе́ніє, // ді́лом і сло́вом, сіє́ вообража́єм."]}],"notes":[]},{"u":"Субота другого тижня Великого посту. Поминання померлих","e":"Saturday of the Second Week of Great Lent. Commemoration of the Departed","secs":[{"h":"Тропар, глас 2","ps":["Апо́столи, му́ченици і проро́ци, / святи́теліє, преподо́бнії і пра́веднії, / до́брі по́двиг соверши́вшії, і ві́ру соблю́дшії, / дерзнове́ніє іму́щії ко Спа́су, / о нас Того́ я́ко Бла́га молі́те спасти́ся, / мо́лимся, ду́шам на́шим.","Сла́ва: Пом'яни́ Го́споди я́ко благ раби́ Твоя́, / і єли́ка в житії́ согріши́ша прості́: / нікто́же бо безгрі́шен, / то́кмо Ти моги́й і преста́вленним да́ти поко́й.","І ни́ні: Богоро́дичен: Ма́ти Свята́я неізрече́ннаго Сві́та, / а́нгельськими Тя пі́сньми почита́юще, / благоче́стно велича́єм."]},{"h":"Кондак, глас 6","ps":["Со святи́ми упоко́й / Христе́, ду́ші раб Твої́х, / іді́же ність болі́знь, ні печа́ль, / ні воздиха́ніє, / но жизнь безконе́чная."]}],"notes":[]},{"u":"Неділя друга Великого посту. Святителя Григорія Палами","e":"Second Sunday of Great Lent. St Gregory Palamas","secs":[{"ps":["По 50-м псалмі́","Сла́ва, глас 8: Покая́нія отве́рзи мі две́рі, Жизнода́вче, / у́тренюєть бо дух мой ко хра́му свято́му Твоєму́, / храм нося́й тіле́сний весь оскверне́н: / но я́ко щедр, очи́сти / благоутро́бною Твоє́ю ми́лостію.","І ни́ні, Богоро́дичен: На спасе́нія стезі́ наста́ви м'я, Богоро́дице, / сту́дними бо окаля́х ду́шу гріхми́, / і в лі́ності все житіє́ моє́ іжди́х: / но Твої́ми моли́твами / ізба́ви м'я от вся́кия нечистоти́.","Та́же, глас 6: Поми́луй м'я, Бо́же, / по вели́цій ми́лості Твоє́й, / і по мно́жеству щедро́т Твої́х, / очи́сти беззако́ніє моє́.","Мно́жества соді́янних мно́ю лю́тих помишля́я окая́нний, / трепе́щу стра́шнаго дне су́днаго: / но наді́яся на ми́лость благоутро́бія Твоєго́, / я́ко Дави́д вопію́ Ті: / поми́луй м'я, Бо́же, / по вели́цій Твоє́й ми́лості."]},{"h":"Кондак 2-ї неділі Великого посту, глас 4","ps":["Ни́ні вре́м'я ді́лательноє яви́ся, / при две́ріх суд, воста́нем у́бо постя́щеся, / принесе́м сле́зи умиле́нія, / ми́лостинями, зову́ще: / согріши́хом па́че піска́ морська́го, / но осла́би, Соді́телю всіх, // я́ко да при́ймем нетлі́нния вінці́."]}],"notes":[]},{"u":"Субота третього тижня Великого посту. Поминання померлих","e":"Saturday of the Third Week of Great Lent. Commemoration of the Departed","secs":[{"h":"Тропар, глас 2","ps":["Апо́столи, му́ченици і проро́ци, / святи́теліє, преподо́бнії і пра́веднії, / до́брі по́двиг соверши́вшії, і ві́ру соблю́дшії, / дерзнове́ніє іму́щії ко Спа́су, / о нас Того́ я́ко Бла́га молі́те спасти́ся, / мо́лимся, ду́шам на́шим.","Сла́ва: Пом'яни́ Го́споди я́ко благ раби́ Твоя́, / і єли́ка в житії́ согріши́ша прості́: / нікто́же бо безгрі́шен, / то́кмо Ти моги́й і преста́вленним да́ти поко́й.","І ни́ні: Богоро́дичен: Ма́ти Свята́я неізрече́ннаго Сві́та, / а́нгельськими Тя пі́сньми почита́юще, / благоче́стно велича́єм."]},{"h":"Кондак, глас 6","ps":["Со святи́ми упоко́й / Христе́, ду́ші раб Твої́х, / іді́же ність болі́знь, ні печа́ль, / ні воздиха́ніє, / но жизнь безконе́чная."]}],"notes":[]},{"u":"Неділя третя Великого посту. Хрестопоклонна","e":"Third Sunday of Great Lent. Veneration of the Cross","secs":[{"ps":["По 50-м псалмі́","Сла́ва, глас 8: Покая́нія отве́рзи мі две́рі, Жизнода́вче, / у́тренюєть бо дух мой ко хра́му свято́му Твоєму́, / храм нося́й тіле́сний весь оскверне́н: / но я́ко щедр, очи́сти / благоутро́бною Твоє́ю ми́лостію.","І ни́ні, Богоро́дичен: На спасе́нія стезі́ наста́ви м'я, Богоро́дице, / сту́дними бо окаля́х ду́шу гріхми́, / і в лі́ності все житіє́ моє́ іжди́х: / но Твої́ми моли́твами / ізба́ви м'я от вся́кия нечистоти́.","Та́же, глас 6: Поми́луй м'я, Бо́же, / по вели́цій ми́лості Твоє́й, / і по мно́жеству щедро́т Твої́х, / очи́сти беззако́ніє моє́.","Мно́жества соді́янних мно́ю лю́тих помишля́я окая́нний, / трепе́щу стра́шнаго дне су́днаго: / но наді́яся на ми́лость благоутро́бія Твоєго́, / я́ко Дави́д вопію́ Ті: / поми́луй м'я, Бо́же, / по вели́цій Твоє́й ми́лості."]},{"h":"Тропар Хреста, глас 1","ps":["Спаси́, Го́споди, лю́ди Твоя́, / і благослови́ достоя́ніє Твоє́, / побі́ди правосла́вним христия́ном на сопроти́вния да́руя, / і Твоє́ сохраня́я Кресто́м Твої́м жи́тельство."]},{"h":"Кондак Хреста, глас 7","ps":["Не ктому́ пла́менноє ору́жіє / храни́ть врат Єде́мських; / на ти́я бо на́йде пресла́вний соу́з дре́во кре́стноє, / сме́ртноє жа́ло, і а́дова побі́да прогна́ся. / Предста́л бо єси́, Спа́се мой, / вопія́ су́щим во а́ді: // вни́діте па́ки в рай."]},{"h":"Тропар на поклоніння Хресту, глас 6","ps":["Кресту́ Твоєму́ покланя́ємся, Влади́ко, / і свято́є воскресе́ніє Твоє́ сла́вим."]}],"notes":[]},{"u":"Субота четвертого тижня Великого посту. Поминання померлих","e":"Saturday of the Fourth Week of Great Lent. Commemoration of the Departed","secs":[{"h":"Тропар, глас 2","ps":["Апо́столи, му́ченици і проро́ци, / святи́теліє, преподо́бнії і пра́веднії, / до́брі по́двиг соверши́вшії, і ві́ру соблю́дшії, / дерзнове́ніє іму́щії ко Спа́су, / о нас Того́ я́ко Бла́га молі́те спасти́ся, / мо́лимся, ду́шам на́шим.","Сла́ва: Пом'яни́ Го́споди я́ко благ раби́ Твоя́, / і єли́ка в житії́ согріши́ша прості́: / нікто́же бо безгрі́шен, / то́кмо Ти моги́й і преста́вленним да́ти поко́й.","І ни́ні: Богоро́дичен: Ма́ти Свята́я неізрече́ннаго Сві́та, / а́нгельськими Тя пі́сньми почита́юще, / благоче́стно велича́єм."]},{"h":"Кондак, глас 6","ps":["Со святи́ми упоко́й / Христе́, ду́ші раб Твої́х, / іді́же ність болі́знь, ні печа́ль, / ні воздиха́ніє, / но жизнь безконе́чная."]}],"notes":[]},{"u":"Неділя четверта Великого посту. Преподобного Іоанна Ліствичника","e":"Fourth Sunday of Great Lent. St John of the Ladder","secs":[{"ps":["По 50-м псалмі́","Сла́ва, глас 8: Покая́нія отве́рзи мі две́рі, Жизнода́вче, / у́тренюєть бо дух мой ко хра́му свято́му Твоєму́, / храм нося́й тіле́сний весь оскверне́н: / но я́ко щедр, очи́сти / благоутро́бною Твоє́ю ми́лостію.","І ни́ні, Богоро́дичен: На спасе́нія стезі́ наста́ви м'я, Богоро́дице, / сту́дними бо окаля́х ду́шу гріхми́, / і в лі́ності все житіє́ моє́ іжди́х: / но Твої́ми моли́твами / ізба́ви м'я от вся́кия нечистоти́.","Та́же, глас 6: Поми́луй м'я, Бо́же, / по вели́цій ми́лості Твоє́й, / і по мно́жеству щедро́т Твої́х, / очи́сти беззако́ніє моє́.","Мно́жества соді́янних мно́ю лю́тих помишля́я окая́нний, / трепе́щу стра́шнаго дне су́днаго: / но наді́яся на ми́лость благоутро́бія Твоєго́, / я́ко Дави́д вопію́ Ті: / поми́луй м'я, Бо́же, / по вели́цій Твоє́й ми́лості."]}],"notes":[]},{"u":"Четвер п’ятого тижня Великого посту. Четвер Великого канону","e":"Thursday of the Fifth Week of Great Lent. Thursday of the Great Canon","secs":[{"h":"Кондак Великого канону, глас 6","ps":["Душе́ моя́, душе́ моя́, воста́ни, что спи́ши; / коне́ць приближа́ється, і і́маши смути́тися: / воспряни́ у́бо, да пощади́ть тя Христо́с Бог, / везді́ сий, і вся ісполня́яй."]}],"notes":[]},{"u":"Похвала Пресвятої Богородиці (Субота Акафіста)","e":"Praise of the Theotokos (Saturday of the Akathist)","secs":[{"h":"Тропар, глас 8","ps":["Повелі́нноє та́йно приє́м в ра́зумі, / в кро́ві Іо́сифові, тща́нієм предста́ безпло́тний, / глаго́ля Неіскусобра́чній: / приклони́вий схожде́нієм небеса́, / вміща́ється неізмі́нно весь в Тя. / Єго́же і ви́дя в ложесна́х Твої́х приє́мша ра́бій зрак, / ужаса́юся зва́ти Тебі́: / ра́дуйся Неві́сто неневі́стная."]},{"h":"Кондак, глас 8","ps":["Взбра́нной воєво́ді побіди́тельная, / я́ко ізба́вльшеся от злих, / благода́рственная воспису́єм Ті раби́ Твої́ Богоро́дице: / но я́ко іму́щая держа́ву непобіди́мую, / от вся́ких нас бід свободи́, да зове́м Ті: / ра́дуйся Неві́сто неневі́стная."]}],"notes":[]},{"u":"Неділя п’ята Великого посту. Преподобної Марії Єгипетської","e":"Fifth Sunday of Great Lent. St Mary of Egypt","secs":[{"ps":["По 50-м псалмі́","Сла́ва, глас 8: Покая́нія отве́рзи мі две́рі, Жизнода́вче, / у́тренюєть бо дух мой ко хра́му свято́му Твоєму́, / храм нося́й тіле́сний весь оскверне́н: / но я́ко щедр, очи́сти / благоутро́бною Твоє́ю ми́лостію.","І ни́ні, Богоро́дичен: На спасе́нія стезі́ наста́ви м'я, Богоро́дице, / сту́дними бо окаля́х ду́шу гріхми́, / і в лі́ності все житіє́ моє́ іжди́х: / но Твої́ми моли́твами / ізба́ви м'я от вся́кия нечистоти́.","Та́же, глас 6: Поми́луй м'я, Бо́же, / по вели́цій ми́лості Твоє́й, / і по мно́жеству щедро́т Твої́х, / очи́сти беззако́ніє моє́.","Мно́жества соді́янних мно́ю лю́тих помишля́я окая́нний, / трепе́щу стра́шнаго дне су́днаго: / но наді́яся на ми́лость благоутро́бія Твоєго́, / я́ко Дави́д вопію́ Ті: / поми́луй м'я, Бо́же, / по вели́цій Твоє́й ми́лості."]}],"notes":[]},{"u":"Субота святого і праведного Лазаря","e":"Saturday of the Holy and Righteous Lazarus","secs":[{"h":"Тропар, глас 1","ps":["О́бщеє воскресе́ніє / пре́жде Твоєя́ Стра́сти увіря́я, / із ме́ртвих воздви́гл єси́ Ла́заря, Христе́ Бо́же. / ті́мже і ми, я́ко о́троци побі́ди зна́менія нося́ще, / Тебі́, Побіди́телю сме́рти вопіє́м: / оса́нна во ви́шніх, // благослове́н Гряди́й во і́м'я Госпо́днє."]},{"h":"Кондак, глас 2","ps":["Всіх ра́дость Христо́с, / І́стина, Світ, Живо́т і ми́ра Воскресе́ніє, / су́щим на землі́ яви́ся Своє́ю бла́гостію, / і бисть о́браз Воскресе́нія, / всім подая́ Боже́ственноє оставле́ніє."]}],"notes":[]},{"u":"Великий понеділок","e":"Great and Holy Monday","secs":[{"h":"Тропар, глас 8","ps":["Се Жени́х гряде́ть в полу́нощі, / і блаже́н раб, Єго́же обря́щеть бдя́ща, / недо́стоїн же па́ки, Єго́же обря́щеть унива́юща. / Блюди́ у́бо, душе́ моя́, / не сном отяготи́ся, / да не сме́рті пре́дана бу́деши, / і Ца́рствія вні затвори́шися, / но воспряни́ зову́щи: / Свят, Свят, Свят єси́, Бо́же, // Богоро́дицею поми́луй нас."]},{"h":"Кондак, глас 8","ps":["Іа́ков рида́ше Іо́сифова лише́нія, / і до́блій сідя́ше на колесни́ці, я́ко цар почита́єм; / єги́птянині бо тогда́ сласте́м не порабо́тав, / воспрославля́шеся от Ві́дущаго челові́чеськая сердця́, // і посила́ющаго віне́ць нетлі́нний."]}],"notes":[]},{"u":"Великий вівторок","e":"Great and Holy Tuesday","secs":[{"h":"Тропар, глас 8","ps":["Се Жени́х гряде́ть в полу́нощі, / і блаже́н раб, Єго́же обря́щеть бдя́ща, / недосто́їн же па́ки, Єго́же обря́щеть унива́юща. / Блюди́ у́бо, душе́ моя́, / не сном отяготи́ся, / да не сме́рті пре́дана бу́деши, / і Ца́рствія вні затвори́шися, / но воспряни́ зову́щи: / Свят, Свят, Свят єси́, Бо́же, // Богоро́дицею поми́луй нас."]},{"h":"Кондак, глас 2","ps":["Час душе́ конця́ поми́сливши, / і посіче́нія смоко́вници убоя́вшися, / да́нний тебі́ тала́нт трудолю́бно ді́лай, окая́нная, / бо́дрствующи і зову́щи: // да не пребу́дем вні черто́га Христо́ва."]}],"notes":[]},{"u":"Велика середа","e":"Great and Holy Wednesday","secs":[{"h":"Тропар, глас 8","ps":["Се Жени́х гряде́ть в полу́нощі, / і блаже́н раб, Єго́же обря́щеть бдя́ща, / недо́стоїн же па́ки, Єго́же обря́щеть унива́юща. / Блюди́ у́бо, душе́ моя́, / не сном отяготи́ся, / да не сме́рті пре́дана бу́деши, / і Ца́рствія вні затвори́шися, / но воспряни́ зову́щи: / Свят, Свят, Свят єси́, Бо́же, // Богоро́дицею поми́луй нас."]},{"h":"Кондак, глас 4","ps":["Па́че блудни́ці, Бла́же, беззако́нновав, / слез ту́чі ніка́коже Тебі́ принесо́х; / но молча́нієм моля́ся припа́даю Ті, / любо́вію облобиза́я пречи́стії Твої́ но́зі, / я́ко да оставле́ніє мні, я́ко Влади́ка пода́си долго́в, / зову́щу Ті, Спа́се: // от скве́рних діл мої́х ізба́ви м'я."]}],"notes":[]},{"u":"Великий четвер","e":"Great and Holy Thursday","secs":[{"h":"Тропар, глас 8","ps":["Єгда́ сла́внії ученици́ / на умове́нії ве́чері просвіща́хуся, / тогда́ Іу́да злочести́вий / сребролю́бієм неду́говав омрача́шеся, / і беззако́нним судія́м Тебе́, Пра́веднаго Судію́, предає́ть. / Виждь, імі́ній рачи́телю, / сих ра́ди удавле́ніє употреби́вша! / Біжи́, неси́тия душі́, / Учи́телю такова́я дерзну́вшия; // І́же о всіх Благи́й, Го́споди, сла́ва Тебі́."]},{"h":"Кондак, глас 2","ps":["Хліб приє́м в ру́ці преда́тель, / сокрове́нно ти́я простира́єть, / і приє́млеть ці́ну Созда́вшаго Свої́ма рука́ма челові́ка, // і неіспра́влен преби́сть Іу́да раб і льстець."]}],"notes":[]},{"u":"Велика п’ятниця","e":"Great and Holy Friday","secs":[{"h":"Тропар, глас 4","ps":["Іскупи́л ни єси́ от кля́тви зако́нния / Честно́ю Твоє́ю Кро́вію, / на Кресті́ пригвозди́вся, і копіє́м пробо́дся, / безсме́ртіє істочи́л єси́ челові́ком, // Спа́се наш, сла́ва Тебі́."]},{"h":"Кондак, глас 8","ps":["Нас ра́ди Расп'я́того прийді́те всі воспої́м, / Того́ бо ви́ді Марі́я і глаго́лаше: // а́ще і расп'я́тіє терпи́ши, Ти єси́ Син і Бог Мой."]}],"notes":[]},{"u":"Велика субота","e":"Great and Holy Saturday","secs":[{"h":"Тропарі, глас 2","ps":["Благообра́зний Іо́сиф, / с дре́ва снем пречи́стоє Ті́ло Твоє́, / плащани́цею чи́стою обви́в, // і воня́ми во гро́бі но́ві покри́в положи́.","Сла́ва: Єгда́ снизше́л єси́ к сме́рті, Животе́ Безсме́ртний, / тогда́ ад умертви́л єси́ блиста́нієм Божества́. / Єгда́ же і уме́ршія от преіспо́дніх воскреси́л єси́, / вся си́ли небе́сния взива́ху: // Жизнода́вче Христе́ Бо́же наш, сла́ва Тебі́.","І ни́ні: Мироно́сицям жена́м при гро́бі предста́в, а́нгел вопія́ше: / ми́ра ме́ртвим суть прили́чна, // Христо́с же істлі́нія яви́ся чуждь."]},{"h":"Кондак, глас 6","ps":["Бе́здну заключи́вий, мертв зри́ться, / і сми́рною і плащани́цею обви́вся, / во гро́бі полага́ється, я́ко сме́ртний, Безсме́ртний; / жени́ же прийдо́ша пома́зати Єго́ ми́ром, / пла́чущи го́рко і вопію́щия: / сія́ Суббо́та єсть Преблагослове́нная, // в не́йже Христо́с усну́в, воскре́снеть тридне́вен."]}],"notes":[]},{"u":"Неділя Антипасхи. Апостола Хоми","e":"Sunday of Thomas. Apostle Thomas","secs":[{"h":"Тропар, глас 7","ps":["Запеча́тану гро́бу, / живо́т от гро́ба возсія́л єси́, Христе́ Бо́же, / і две́рем заключе́нним, / ученико́м предста́л єси́, / всіх воскресе́ніє; / дух пра́вий ті́ми обновля́я нам, // по вели́цій Твоє́й ми́лості."]},{"h":"Кондак, глас 8","ps":["Любопи́тною десни́цею / жизнопода́тельная Твоя́ ре́бра Фома́ іспита́, Христе́ Бо́же; / созаключе́нним бо две́рем я́ко вшел єси́, / с про́чими апо́столи вопія́ше Тебі́: // Госпо́дь єси́ і Бог мой."]},{"h":"Величання","ps":["Велича́єм Тя, / Живода́вче Христе́, / нас ра́ди во ад сше́дшаго / і с Собо́ю вся // воскреси́вшаго."]}],"notes":[]},{"u":"Неділя 3-тя по Пасці. Святих жон-мироносиць","e":"Third Sunday after Pascha. The Holy Myrrh-Bearing Women","secs":[{"h":"Тропар, глас 2","ps":["Єгда́ снизше́л єси́ к сме́рті, Животе́ Безсме́ртний, / тогда́ ад умертви́л єси́ блиста́нієм Божества́. / Єгда́ же і уме́ршія от преіспо́дніх воскреси́л єси́, / вся си́ли небе́сния взива́ху: // Жизнода́вче Христе́ Бо́же наш, сла́ва Тебі́.","Сла́ва: Благообра́зний Іо́сиф с дре́ва снем Пречи́стоє Твоє́ ті́ло, / плащани́цею чи́стою обви́в, / і благоуха́ньми во гро́бі но́ві закри́в положи́; / но тридне́вен воскре́сл єси́, Го́споди, // подая́й ми́рові ве́лію ми́лость.","І ни́ні: Мироно́сицям жена́м при гро́бі предста́в а́нгел, вопія́ше: / ми́ра ме́ртвим суть прили́чна / Христо́с же істлі́нія яви́ся чуждь. / Но возопи́йте: воскре́се Госпо́дь, // подая́й ми́рові ве́лію ми́лость."]},{"h":"Кондак, глас 2","ps":["Ра́доватися мироно́сицям повелі́л єси́, / плач прама́тере Є́ви утоли́л єси́ / воскресе́нієм Твої́м, Христе́ Бо́же, / апо́столом же Твої́м пропові́дати повелі́л єси́: // Спас воскре́се от гро́ба."]},{"h":"Величання (якщо храм цього празника)","ps":["Велича́єм вас святи́я мироно́сиці, і чтим святу́ю па́м'ять ва́шу: ви бо мо́лите о нас Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Неділя 4-та по Пасці. Про розслабленого","e":"Fourth Sunday after Pascha. The Paralytic","secs":[{"h":"Тропар, глас 3","ps":["Да веселя́ться небе́сная, / да ра́дуються земна́я, / я́ко сотвори́ держа́ву / ми́шцею Своє́ю Госпо́дь, / попра́ сме́ртію смерть, / пе́рвенець ме́ртвих бисть; / із чре́ва а́дова ізба́ви нас, // і подаде́ ми́рові ве́лію ми́лость."]},{"h":"Кондак, глас 3","ps":["Ду́шу мою́, Го́споди, во грісі́х вся́чеських, / і безмі́стними дія́ньми лю́ті разсла́блену, / воздви́гни Боже́ственним Твої́м предста́тельством, / я́коже і разсла́бленнаго воздви́гл єси́ дре́вле, / да зову́ Ті спаса́єм: // Ще́дрий, сла́ва, Христе́, держа́ві Твоє́й."]}],"notes":[]},{"u":"Преполовення П’ятдесятниці","e":"Mid-Pentecost","secs":[{"h":"Тропар, глас 8","ps":["Преполови́вшуся пра́зднику, / жа́ждущую ду́шу мою́ благоче́стія напо́й вода́ми, / я́ко всім, Спа́се, возопи́л єси́: / жа́ждай да гряде́ть ко Мні і да піє́ть. // Істо́чниче жи́зні на́шея, Христе́ Бо́же сла́ва Тебі́."]},{"h":"Кондак, глас 4","ps":["Пра́зднику зако́нному преполовля́ющуся, / всіх Тво́рче і Влади́ко, / к предстоя́щим глаго́лал єси́, Христе́ Бо́же: / прийді́те і почерпі́те во́ду безсме́ртія. / Ті́мже Тебе́ припа́даєм, і ві́рно вопіє́м: / щедро́ти Твоя́ да́руй нам, // Ти бо єси́ Істо́чник жи́зні на́шея."]},{"h":"Задостойник, глас 8","ps":["Чу́жде ма́терем ді́вство, / і стра́нно ді́вам діторожде́ніє, / на Тебі́ Богоро́дице, обоя́ устро́їшася. / Тім Тя вся племена́ земна́я / непреста́нно велича́єм.","Примечаніє. Єтот же задостойник поє́ться і в отда́ніє пра́здника Преполове́нія, в прочіє дні попра́зднства Преполове́нія – задостойник Па́схи."]}],"notes":[]},{"u":"Неділя 5-та по Пасці. Про самарянку","e":"Fifth Sunday after Pascha. The Samaritan Woman","secs":[{"h":"Тропар Неділі про самарянку, глас 4","ps":["Сві́тлую воскресе́нія про́повідь / от А́нгела уві́дівше Госпо́дні учени́ци / і пра́діднєє осужде́ніє отве́ргше, / апо́столом хва́лящася глаго́лаху: / іспрове́ржеся смерть, / воскре́се Христо́с Бог, // да́руяй ми́рові ве́лію ми́лость."]},{"h":"Кондак Неділі про самарянку, глас 8","ps":["Ві́рою прише́дшая на кла́дязь самаряни́ня, / ви́дя Тя прему́дрости во́ду, / є́юже напоі́шася оби́льно, // Ца́рствіє ви́шнєє наслі́дова ві́чно, я́ко присносла́вная."]},{"h":"Тропар Преполовення, глас 8","ps":["Преполови́вшуся пра́зднику, / жа́ждущую ду́шу мою́ благоче́стія напо́й вода́ми, / я́ко всім, Спа́се, возопи́л єси́: / жа́ждай да гряде́ть ко Мні і да піє́ть. // Істо́чниче жи́зні на́шея, Христе́ Бо́же сла́ва Тебі́."]},{"h":"Кондак Преполовення, глас 4","ps":["Пра́зднику зако́нному преполовля́ющуся, / всіх Тво́рче і Влади́ко, / к предстоя́щим глаго́лал єси́, Христе́ Бо́же: / прийді́те і почерпі́те во́ду безсме́ртія. / Ті́мже Тебе́ припа́даєм, і ві́рно вопіє́м: / щедро́ти Твоя́ да́руй нам, // Ти бо єси́ Істо́чник жи́зні на́шея."]},{"h":"Задостойник Преполовення, глас 8","ps":["Чу́жде ма́терем ді́вство, / і стра́нно ді́вам діторожде́ніє, / на Тебі́ Богоро́дице, обоя́ устро́їшася. / Тім Тя вся племена́ земна́я / непреста́нно велича́єм."]}],"notes":[]},{"u":"Неділя 6-та по Пасці. Про сліпородженого","e":"Sixth Sunday after Pascha. The Man Born Blind","secs":[{"h":"Тропар, глас 5","ps":["Собезнача́льноє Сло́во Отцю́ і Ду́хові, / от Ді́ви ро́ждшеєся на спасе́ніє на́ше, / воспої́м, ві́рнії, і поклоні́мся, / я́ко благоволи́ пло́тію взи́ти на крест, / і смерть претерпі́ти, / і воскреси́ти уме́ршія // сла́вним воскресе́нієм Свої́м."]},{"h":"Кондак, глас 4","ps":["Душе́внима очи́ма осліпле́н, / к Тебі́, Христе́, прихожду́, / я́коже сліпи́й от рожде́нія, / покая́нієм зову́ Ті: // Ти су́щих во Тьмі Світ пресві́тлий."]}],"notes":[]},{"u":"Неділя 7-ма по Пасці. Святих отців I Вселенського собору","e":"Seventh Sunday after Pascha. The Holy Fathers of the First Ecumenical Council","secs":[{"h":"Тропар, глас 8","ps":["Препросла́влен єси́, Христе́ Бо́же наш, / світи́ла на землі́ отці́ на́ша основа́вий, / і ті́ми ко і́стинній ві́рі вся ни наста́вивий, // Многоблагоутро́бне, сла́ва Тебі́."]},{"h":"Кондак, глас 8","ps":["Апо́стол пропові́даніє, і оте́ць догма́ти, / Це́ркві єди́ну ві́ру запечатлі́ша, / я́же і ри́зу нося́щи і́стини, / істка́ну от є́же сви́ше богосло́вія, // ісправля́єть і сла́вить благоче́стія вели́коє та́їнство."]}],"notes":[]},{"u":"Трійцька батьківська субота","e":"Trinity Saturday of the Departed","secs":[{"h":"Тропар, глас 8","ps":["Глубино́ю му́дрости человіколю́бно вся стро́яй, / і поле́зноє всім подава́яй, / єди́не Соді́телю, упоко́й, Го́споди, ду́ші раб Твої́х; / на Тя бо упова́ніє возложи́ша, / Творця́ і Зижди́теля, і Бо́га на́шего.","Сла́ва, і ни́ні: Богоро́дичен:","Тебі́ і сті́ну і приста́нище і́мами, / і моли́твенницю благоприя́тну к Бо́гу, / Єго́же родила́ єси́, Богоро́дице безневі́стная, ві́рних спасе́ніє."]},{"h":"Кондак, глас 6","ps":["Со святи́ми упоко́й, / Христе́, ду́ші раб Твої́х, / іді́же ність болі́знь, ні печа́ль, ні воздиха́ніє, / но жизнь безконе́чная."]}],"notes":[]},{"u":"Неділя всіх святих","e":"Sunday of All Saints","secs":[{"h":"Тропар воскресний, глас 8","ps":["С висоти́ снизше́л єси́, Благоутро́бне, / погребе́ніє прия́л єси́ тридне́вноє, / да нас свободи́ши страсте́й, // Животі́ і воскресе́ніє на́ше, Го́споди, сла́ва Тебі́."]},{"h":"Тропар святим, глас 4","ps":["І́же во всем ми́рі му́ченик Твої́х, / я́ко багряни́цею і ви́ссом, / кровми́ Це́рков Твоя́ украси́вшися, / ті́ми вопіє́ть Ті, Христе́ Бо́же: / лю́дем Твої́м щедро́ти Твоя́ низпосли́, / мир жи́тельству Твоєму́ да́руй, // і душа́м на́шим ве́лію ми́лость."]},{"h":"Кондак, глас 8","ps":["Я́ко нача́тки єстества́, Насади́телю тва́рі / вселе́нная прино́сить Ті, Го́споди, богоно́сния му́ченики: / тіх моли́твами в ми́рі глубо́ці, // Це́рков Твою́, жи́тельство Твоє́ Богоро́дицею соблюди́, Многоми́лостиве."]}],"notes":[]},{"u":"Святих отців (неділя перед Різдвом)","e":"Holy Fathers (Sunday before the Nativity)","secs":[{"h":"Тропар, глас 2","ps":["Ве́лія ві́ри ісправле́нія: / во істо́чниці пла́мене, я́ко на воді́ упокоє́нія, / святі́ї тріє́ о́троци ра́довахуся, / і проро́к Данії́л львом па́стир, я́ко овця́м, явля́шеся. // Тіх моли́твами, Христе́ Бо́же, спаси́ ду́ші на́ша."]},{"h":"Кондак, глас 6","ps":["Рукопи́саннаго о́браза не поче́тше, / но Неопи́санним Существо́м защити́вшеся, треблаже́ннії, / в по́двизі огня́ просла́вистеся; / среді́ же пла́мене нестерпи́маго стоя́ще, Бо́га призва́сте: / ускори́, о Ще́дрий! / І потщи́ся, я́ко ми́лостив, в по́мощ на́шу, // я́ко мо́жеши хотя́й."]},{"h":"Кондак (якщо в передсвятті), глас 1","ps":["Весели́ся, Вифлеє́ме, Євфра́фо, гото́вися: / се бо А́гниця, Па́стиря вели́каго во утро́бі нося́щи, є́же роди́ти тщи́ться, / Єго́же зря́ще, Богоно́снії отці́ веселя́ться, / с па́стирми пою́ще Ді́ву доя́щую."]}],"notes":[]},{"u":"Навечір’я Різдва Христового (Святвечір)","e":"Eve of the Nativity of Christ (Holy Supper)","secs":[{"h":"Тропар, глас 4","ps":["Написова́шеся іногда́ со ста́рцем Іо́сифом, / я́ко от сі́мене Дави́дова, во Вифлеє́мі Марія́м, / чревонося́щи безсі́менноє Рожде́ніє. / Наста́ же вре́м'я рождества́, / і мі́сто ні єди́ноже бі обита́лищу, / но, я́коже кра́сная пала́та, / верте́п Цари́це показа́шеся. // Христо́с ражда́ється пре́жде па́дший воскреси́ти о́браз."]},{"h":"Кондак, глас 3","ps":["Ді́ва днесь Преві́чноє Сло́во / во верте́пі гряде́ть роди́ти неізрече́нно; / лику́й, вселе́нная, усли́шавши, / просла́ви со А́нгели і па́стирми // хотя́щаго яви́тися Отроча́ Мла́до, Преві́чнаго Бо́га."]}],"notes":[]},{"u":"Навечір’я Богоявлення (Хрещенський святвечір)","e":"Eve of Theophany","secs":[{"h":"Тропар, глас 4","ps":["Возвраща́шеся іногда́ Іорда́н ріка́ ми́лотію Єлисе́євою, / возне́сшуся Ілії́, / і разділя́хуся во́ди сю́ду і сю́ду / і бисть єму́ сух путь, і́же мо́крий, / во о́браз воі́стину Креще́нія, / і́мже ми теку́щеє житія́ прехо́дим ше́ствіє: // Христо́с яви́ся во Іорда́ні, освяти́ти во́ди."]},{"h":"Кондак, глас 4","ps":["Во струя́х днесь Іорда́нських бив, Госпо́дь / Іоа́нну вопіє́ть: / не убо́йся крести́ти М'я, / спасти́ бо прийдо́х / Ада́ма первозда́ннаго.","Ін конда́к, глас 2","Всіх, Христе́, Благоутро́бне, от'є́мляй прегріше́ній мно́жество / ми́лости ра́ди безмі́рния, / Іорда́нськими во́дами крести́тися гряде́ши, я́ко Челові́к, / оде́ждею м'я одіва́я, // сла́ви дре́внія обнаже́нна лю́ті."]}],"notes":[]},{"u":"Початок індикта — церковне новоліття","e":"Beginning of the Indiction — the Church New Year","secs":[{"h":"Тропар, глас 2","ps":["Всея́ тва́рі Соді́телю, / времена́ і лі́та во Своє́й вла́сті положи́вий, / благослови́ ві́нець лі́та бла́гости Твоєя́, Го́споди, / сохраня́я в ми́рі лю́ди і град Твой // моли́твами Богоро́диці і спаси́ ни."]},{"h":"Кондак, глас 2","ps":["Во Ви́шніх живи́й, Христе́ Царю́, / всіх ви́димих і неви́димих Тво́рче і Зижди́телю, / І́же дні і но́щі, времена́ і лі́та сотвори́вий, / благослови́ ни́ні віне́ць лі́та, / соблюди́ і сохрани́ в ми́рі град і лю́ди Твоя́, // Многоми́лостиве."]}],"notes":[]},{"u":"Димитріївська батьківська субота","e":"Saturday of St Demetrius of the Departed","secs":[{"h":"Тропар, глас 2","ps":["Апо́столи, му́ченици і проро́ци, / святи́теліє, преподо́бнії і пра́веднії, / до́брі по́двиг соверши́вшії і ві́ру соблю́дшії, / дерзнове́ніє іму́щії ко Спа́су, / о нас Того́,́ я́ко Бла́га, молі́те // спасти́ся, мо́лимся, душа́м на́шим.","Сла́ва: Пом'яни́, Го́споди, я́ко Благ, раби́ Твоя́, / і єли́ка в житії́ согріши́ша, прості́: / нікто́же бо безгрі́шен, то́кмо Ти, // моги́й і преста́вленним да́ти поко́й.","І ни́ні: Богоро́дичен: Тебі́ і Сті́ну і Приста́нище і́мами, / і Моли́твенницю благоприя́тну к Бо́гу, // Єго́же родила́ єси́, Богоро́дице Безневі́стная, ві́рних спасе́ніє."]},{"h":"Кондак, глас 8","ps":["Со святи́ми упоко́й, / Христе́, / ду́ші раб Твої́х, / іді́же ність болі́знь, ні печа́ль, / ні воздиха́ніє, // но жизнь безконе́чная."]}],"notes":[]},{"u":"Святих праотців","e":"Holy Forefathers","secs":[{"h":"Тропар, глас 2","ps":["Ві́рою пра́отці оправда́л єси́, / от язи́к ті́ми предобручи́вий Це́рков; / хва́ляться в сла́ві святі́ї, / я́ко от сі́мене їх єсть Плод благосла́вен, / без сі́мене Ро́ждшая Тя. / Тіх моли́твами, Христе́ Бо́же, поми́луй нас."]},{"h":"Кондак, глас 6","ps":["Рукопи́саннаго о́браза не поче́тше, / но неопи́санним Существо́м защити́вшеся, треблаже́ннії, / в по́двизі огня́ просла́вистеся, / среді́ же пла́мене нестерпи́маго стоя́ще, Бо́га призва́сте: / ускори́, о Ще́дрий, і потщи́ся, я́ко Ми́лостив, в по́мощ на́шу, / я́ко мо́жеши хотя́й."]}],"notes":[]}];
export default D;
